// Extract the important fields and compute file path
const item = $input.item.json;

// Get title - try multiple locations
let title = 'Untitled';
try {
  if (item.properties?.title?.title?.[0]?.plain_text) {
    title = item.properties.title.title[0].plain_text;
  } else if (item.properties?.Name?.title?.[0]?.plain_text) {
    title = item.properties.Name.title[0].plain_text;
  } else {
    // Try any title-type property
    for (const [key, val] of Object.entries(item.properties || {})) {
      if (val.type === 'title' && val.title?.[0]?.plain_text) {
        title = val.title[0].plain_text;
        break;
      }
    }
  }
} catch(e) { title = item.id; }

// Sanitize title for use as filename
const safeTitle = title
  .replace(/[\/\\:*?"<>|]/g, '-')
  .replace(/\s+/g, ' ')
  .trim();

const parentType = item.parent?.type || 'workspace';
const parentDbId = item.parent?.database_id?.replaceAll('-', '') || null;
const parentPageId = item.parent?.page_id?.replaceAll('-', '') || null;

return {
  json: {
    id: item.id,
    title: safeTitle,
    originalTitle: title,
    parentType: parentType,
    parentDbId: parentDbId,
    parentPageId: parentPageId,
    lastEditedTime: item.last_edited_time,
    url: item.url,
    properties: item.properties
  }
};

const pageData = $('Route by Parent Type').item.json;
const blocksData = $input.item.json;

function blockToMarkdown(block) {
  const type = block.type;
  const b = block[type];
  if (!b) return '';

  const getText = (richText) => {
    if (!richText) return '';
    return richText.map(t => {
      let text = t.plain_text || '';
      if (t.annotations?.bold) text = `**${text}**`;
      if (t.annotations?.italic) text = `*${text}*`;
      if (t.annotations?.code) text = `\`${text}\``;
      if (t.href) text = `[${text}](${t.href})`;
      return text;
    }).join('');
  };

  switch(type) {
    case 'paragraph': return getText(b.rich_text) + '\n\n';
    case 'heading_1': return `# ${getText(b.rich_text)}\n\n`;
    case 'heading_2': return `## ${getText(b.rich_text)}\n\n`;
    case 'heading_3': return `### ${getText(b.rich_text)}\n\n`;
    case 'bulleted_list_item': return `- ${getText(b.rich_text)}\n`;
    case 'numbered_list_item': return `1. ${getText(b.rich_text)}\n`;
    case 'to_do': return `- [${b.checked ? 'x' : ' '}] ${getText(b.rich_text)}\n`;
    case 'toggle': return `> ${getText(b.rich_text)}\n\n`;
    case 'quote': return `> ${getText(b.rich_text)}\n\n`;
    case 'callout': return `> 💡 ${getText(b.rich_text)}\n\n`;
    case 'code': return `\`\`\`${b.language || ''}\n${getText(b.rich_text)}\n\`\`\`\n\n`;
    case 'divider': return `---\n\n`;
    case 'image': {
      const url = b.external?.url || b.file?.url || '';
      const caption = getText(b.caption) || 'image';
      return `![${caption}](${url})\n\n`;
    }
    case 'bookmark': return `[${getText(b.caption) || b.url}](${b.url})\n\n`;
    case 'child_page': return `📄 [${b.title}](./${pageData.title}/${b.title}.md)\n\n`;
    case 'child_database': return `🗄️ [${b.title}](./${pageData.title}/${b.title}/)\n\n`;
    case 'table_of_contents': return `<!-- TOC -->\n\n`;
    default: return '';
  }
}

const blocks = blocksData.results || [];
let md = `# ${pageData.title}\n\n`;
md += `> Last edited: ${pageData.lastEditedTime}\n> Notion URL: ${pageData.url}\n\n---\n\n`;

for (const block of blocks) {
  md += blockToMarkdown(block);
}

// File path: top-level = root of repo
const filePath = `${pageData.title}.md`;

return [{
  json: {
    ...pageData,
    markdown: md,
    filePath: filePath,
    commitMessage: `backup: update ${pageData.title}`
  }
}];

// Both merged by position, so $input.all() gives [blocksItem, dbInfoItem]
// entryData lives in Merge DB Data upstream

// console.log(JSON.stringify($input.item.json));

const merged = $input.item.json;
const blocksData = merged.blockdata;  // Get Blocks 的結果
const dbInfo = merged.dbinfo;      // Get DB Info 的結果
const entryData = $('Enrich Entry with Properties').item.json;

// Get DB title
let dbTitle = 'Unknown DB';
try {
  dbTitle = dbInfo.title?.[0]?.plain_text || dbInfo.id;
} catch(e) {}
const safeDbTitle = dbTitle.replace(/[\/\\:*?"<>|]/g, '-').trim();

// Helper to extract property value as string
function propToString(prop) {
  if (!prop) return '';
  switch(prop.type) {
    case 'title': return prop.title?.map(t => t.plain_text).join('') || '';
    case 'rich_text': return prop.rich_text?.map(t => t.plain_text).join('') || '';
    case 'number': return prop.number?.toString() || '';
    case 'select': return prop.select?.name || '';
    case 'multi_select': return prop.multi_select?.map(s => s.name).join(', ') || '';
    case 'status': return prop.status?.name || '';
    case 'date': return prop.date?.start || '';
    case 'checkbox': return prop.checkbox ? 'true' : 'false';
    case 'url': return prop.url || '';
    case 'email': return prop.email || '';
    case 'phone_number': return prop.phone_number || '';
    case 'people': return prop.people?.map(p => p.name).join(', ') || '';
    case 'created_time': return prop.created_time || '';
    case 'last_edited_time': return prop.last_edited_time || '';
    case 'formula': return prop.formula?.string || prop.formula?.number?.toString() || prop.formula?.boolean?.toString() || '';
    default: return JSON.stringify(prop);
  }
}

// Blocks → Markdown
function blockToMarkdown(block) {
  const type = block.type;
  const b = block[type];
  if (!b) return ''; 
  const getText = (richText) => {
    if (!richText) return '';
    return richText.map(t => {
      let text = t.plain_text || '';
      if (t.annotations?.bold) text = `**${text}**`;
      if (t.annotations?.italic) text = `*${text}*`;
      if (t.annotations?.code) text = `\`${text}\``;
      if (t.href) text = `[${text}](${t.href})`;
      return text;
    }).join('');
  };

  switch(type) {
    case 'paragraph': return getText(b.rich_text) + '\n\n';
    case 'heading_1': return `# ${getText(b.rich_text)}\n\n`;
    case 'heading_2': return `## ${getText(b.rich_text)}\n\n`;
    case 'heading_3': return `### ${getText(b.rich_text)}\n\n`;
    case 'bulleted_list_item': return `- ${getText(b.rich_text)}\n`;
    case 'numbered_list_item': return `1. ${getText(b.rich_text)}\n`;
    case 'to_do': return `- [${b.checked ? 'x' : ' '}] ${getText(b.rich_text)}\n`;      
    case 'quote': return `> ${getText(b.rich_text)}\n\n`;
    // case 'callout':
        // const icon = b.icon?.emoji || '💡';
        // return `> ${icon} ${getText(b.rich_text)}\n\n`;
    case 'code': return `\`\`\`${b.language || ''}\n${getText(b.rich_text)}\n\`\`\`\n\n`;
    case 'divider': return `---\n\n`;
    case 'image': {
      const url = b.external?.url || b.file?.url || '';
      return `![image](${url})\n\n`;
    }
    case 'bookmark': return `[${getText(b.caption) || b.url}](${b.url})\n\n`;
    default: return '';
  }
}

// YAML frontmatter from properties
const props = entryData.fullProperties || {};
let frontmatter = '---\n';
for (const [key, val] of Object.entries(props)) {
  const strVal = propToString(val).replace(/'/g, "''");
  frontmatter += `${key}: '${strVal}'\n`;
}
frontmatter += `---\n\n`;

// Body
const blocks = blocksData.results || [];
let body = '';
for (const block of blocks) {
  body += blockToMarkdown(block);
}

const md = frontmatter + `# ${entryData.title}\n\n` + (body || '_No content_\n');
const filePath = `${safeDbTitle}/${entryData.title}.md`;

return {
  json: {
    ...entryData,
    dbTitle: safeDbTitle,
    markdown: md,
    filePath: filePath,
    commitMessage: `backup: update ${safeDbTitle}/${entryData.title}`
  }
};

// Prepare the payload for GitHub create/update file API
const fileData = $('Batch (3 at a time)').item.json;
const shaResponse = $input.item.json;

// Base64 encode the markdown content
const content = Buffer.from(fileData.markdown, 'utf8').toString('base64');

// If file exists, sha is required to update
const sha = shaResponse?.sha || null;

return [{
  json: {
    ...fileData,
    base64Content: content,
    existingSha: sha,
    commitMessage: `n8n backup for changes dated ${fileData.lastEditedTime?.slice(0, 10)}`
  }
}];

// Attach full properties from GET /pages/{id} back onto the entry metadata
const routeData = $('Route by Parent Type').item.json;
const fullPage = $input.item.json;

return {
  json: {
    ...routeData,
    fullProperties: fullPage.properties
  }
};

